import{_ as t,c as a,o as r,ah as o}from"./chunks/framework.PvdZnrZd.js";const u=JSON.parse('{"title":"Order Prepare Status","description":"Order Prepare Status","frontmatter":{"title":"Order Prepare Status","description":"Order Prepare Status","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/order/order-prepare-status.md","filePath":"zenith/order/order-prepare-status.md"}'),l={name:"zenith/order/order-prepare-status.md"};function n(s,e,p,i,d,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<p><strong><a href="/zenith/introduction/">Multivendor Marketplace for Shopify</a> | Order Prepare Status Feature</strong><br> With this feature, the seller can intimate admin about the status of the order step by step.</p><p>When the order is placed &amp; received then admin &amp; seller can mark the order prepare status on various stages.</p><h2 id="stage-1" tabindex="-1">Stage-1 <a class="header-anchor" href="#stage-1" aria-label="Permalink to &quot;Stage-1&quot;">​</a></h2><p>To enable this feature, visit the Configuration &gt;&gt;&gt; Order configuration &gt;&gt;&gt; and enable Order status from there.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/orderprepareconfigenable.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/orderprepareconfigenable.webp" alt="order"></a></p><h2 id="stage-2" tabindex="-1">Stage-2 <a class="header-anchor" href="#stage-2" aria-label="Permalink to &quot;Stage-2&quot;">​</a></h2><p>Once an order is placed, the shipping status will set to &quot;collect&quot; at the seller side and &quot;busy &quot; at the admin side.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/busystatus.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/busystatus.webp" alt="vendor"></a></p><h2 id="stage-3" tabindex="-1">Stage-3 <a class="header-anchor" href="#stage-3" aria-label="Permalink to &quot;Stage-3&quot;">​</a></h2><p>Now the seller will click the &quot;collect&quot; button for a corresponding order to notify the admin to collect the product. Here admin will receive an email regarding the same.</p><p>Now at the admin side, the shipping status of that order is in the &quot;Collect&quot; state and at the seller side, it&#39;s &quot;Pending&quot;.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/collectsellerpanel.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/collectsellerpanel.webp" alt="collect"></a></p><h2 id="stage-4" tabindex="-1">Stage-4 <a class="header-anchor" href="#stage-4" aria-label="Permalink to &quot;Stage-4&quot;">​</a></h2><p>Once admin clicks the &quot;collect&quot; button for an order, the status changes to &quot;collecting&quot; at both sides.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/collectingadminapnel.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/collectingadminapnel.webp" alt="order status"></a></p><h2 id="stage-5" tabindex="-1">Stage-5 <a class="header-anchor" href="#stage-5" aria-label="Permalink to &quot;Stage-5&quot;">​</a></h2><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/collectedadminpanle.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/collectedadminpanle.webp" alt="order status"></a></p><p>Now the admin collects the product, to notify the seller he clicks the collecting button. Here the status changes to &quot;collected&quot; at both sides.</p><p>NOTE:  In case, the seller is unable to collect the order in the mentioned time interval, then the order gets expired, then, in this case, the order gets refunded.</p><h3 id="multivendor-marketplace-for-shopify-order-prepare-status-feature-demo" tabindex="-1">Multivendor Marketplace for Shopify | Order prepare status feature: Demo <a class="header-anchor" href="#multivendor-marketplace-for-shopify-order-prepare-status-feature-demo" aria-label="Permalink to &quot;Multivendor Marketplace for Shopify | Order prepare status feature: Demo&quot;">​</a></h3><p>Check out: <a href="https://multivendor-marketplace-5.myshopify.com/" target="_blank" rel="noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></p>',21)])])}const g=t(l,[["render",n]]);export{u as __pageData,g as default};
